import React, { useState } from 'react';
import './Header.css';

function Header() {
  const [searchQuery, setSearchQuery] = useState('');
  const [showExplore, setShowExplore] = useState(false);

  const handleExploreToggle = () => {
    setShowExplore((prev) => !prev);
  };

  const exploreCategories = [
    'Trending',
    'Music',
    'Gaming',
    'News',
    'Sports',
    'Education',
    'Movies',
  ];

  return (
    <header className="header">
      <div className="container">
        <i className="fa-brands fa-youtube youtube"></i>

        <div className="mic">
          <input
            type="text"
            className="search-bar"
            placeholder="Search..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <i className="fas fa-microphone"></i>
        </div>

        <div className="icons">
          <i className="fas fa-video"></i>
          <i className="fas fa-bell"></i>
          <i className="fas fa-user"></i>
          <div className="explore-wrapper">
            <button className="explore-button" onClick={handleExploreToggle}>
              Explore <i className="fas fa-chevron-down"></i>
            </button>
            {showExplore && (
              <ul className="explore-dropdown">
                {exploreCategories.map((category, index) => (
                  <li key={index} className="explore-item">
                    {category}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

export default Header;
